
-- Seed script for Family Travel Directory - destinations table
-- Run this in Supabase SQL Editor at https://supabase.com/dashboard/project/llnflvnjinavbtqadgyu/sql/new

-- Create the destinations table
CREATE TABLE IF NOT EXISTS destinations (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  city TEXT NOT NULL,
  country TEXT NOT NULL,
  category TEXT NOT NULL,
  description TEXT NOT NULL,
  age_range TEXT NOT NULL,
  safety_rating NUMERIC NOT NULL DEFAULT 4.5,
  price_range TEXT NOT NULL DEFAULT '$$',
  popularity INTEGER NOT NULL DEFAULT 50,
  location TEXT NOT NULL,
  best_time TEXT NOT NULL DEFAULT 'Year-round',
  image_url TEXT,
  amenities TEXT[] DEFAULT '{}',
  safety_features TEXT[] DEFAULT '{}',
  tips_and_tricks TEXT[] DEFAULT '{}',
  gallery TEXT[] DEFAULT '{}',
  commission_rate TEXT DEFAULT '5%',
  seo_keywords TEXT[] DEFAULT '{}',
  metadata JSONB DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable Row Level Security
ALTER TABLE destinations ENABLE ROW LEVEL SECURITY;

-- Create a policy to allow public read access (for the public-facing site)
CREATE POLICY "Allow public read access" 
  ON destinations 
  FOR SELECT 
  USING (true);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('tokyo-001', 'Tokyo Disneyland', 'Tokyo', 'Japan', 'Theme Parks', 'The ultimate family destination with classic Disney magic. Two incredible parks with exceptional safety standards, stroller rentals, baby care centers, and numerous family-friendly restaurants.', '3-12', 4.9, '$$$', 98, '1-1 Maihama, Urayasu, Chiba', 'Weekdays, September-November', 'https://images.unsplash.com/photo-1775144113652-6592b3ebeb06?w=800&q=80', '{"Stroller Rental","Baby Care Centers","Family Restrooms","Height Restrictions","First Aid"}'::text[], '{"Trained Staff","Emergency Protocols","Lost Child Centers","Allergy-Friendly Options"}'::text[], '{"Go on a Tuesday or Wednesday — weekend crowds are 3x worse and you''ll spend half your day in line.","Bring your own snacks. The park allows outside food and a packed lunch saves $40+ per person.","Use the Disney Resort app to book ''Priority Pass'' slots — they''re free and save 60-90 minutes of waiting per ride.","The Baby Care Centers have private nursing rooms, microwaves for bottles, and vending machines with formula.","If your kid gets overwhelmed, head to the ''Quiet Areas'' near It''s a Small World — soundproofed and rarely crowded."}'::text[], '{"https://images.unsplash.com/photo-1776619455134-1c4f2f1422cb?w=800&q=80","https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80","https://images.unsplash.com/photo-1513889961551-628c1e5e2ee9?w=800&q=80"}'::text[], '8%', '{"Tokyo Disneyland","family theme park Japan","kid-friendly Tokyo"}'::text[], '{"parent_story": {"title": "The meltdown that turned into our best memory", "excerpt": "Our 4-year-old screamed for 20 minutes outside Space Mountain. Too short. Too scary. We almost left. Then a cast member took us to the backlot to watch the parade setup. She spent an hour waving at characters. That moment \u2014 a stranger''s kindness \u2014 saved our day.", "author": "Sarah, mom of 2 from Melbourne", "fullStory": "We''d planned this trip for 6 months. The moment we got to Space Mountain, our youngest had a full meltdown. Too tall? No. Too scary? Also no. She was mad she COULDN''T ride. A cast member noticed, knelt down, and whispered something to her. Next thing we knew, she was helping set up the parade floats backstage. She still talks about it 2 years later."}, "itinerary_comparison": {"halfDay": "Ride 3-4 attractions, lunch, character meet, leave by 3pm", "fullDay": "Ride 6-8 attractions, both parks, parade, dinner, fireworks", "bestFor": "Ages 3-12, especially Disney fans"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('tokyo-002', 'Ueno Zoo & Museums', 'Tokyo', 'Japan', 'Zoos & Aquariums', 'Japan''s oldest zoo in beautiful Ueno Park. Perfect for younger children with pandas, gorillas, and a children''s zoo. Stroller-friendly paths and plenty of shaded areas.', '0-12', 4.7, '$', 87, '9-83 Uenokoen, Taito City, Tokyo', 'Morning, Spring/Fall', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80', '{"Stroller Access","Nursing Rooms","Play Areas","Picnic Areas"}'::text[], '{"Animal Safety Barriers","First Aid Stations","Clear Signage","Security Patrols"}'::text[], '{"Arrive at 9:30 AM when the gates open. The pandas are most active in the first hour before it gets hot.","The zoo is huge. Skip the reptile house if your kids are under 6 — it''s dark and the snakes spook most toddlers.","Bring a picnic. There are shaded benches everywhere and the zoo food is overpriced.","Combine with the National Museum next door — it''s free for kids under 18 and has interactive exhibits.","The monorail from Ueno Station has elevator access at every exit. No stairs needed with a stroller."}'::text[], '{"https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80","https://images.unsplash.com/photo-1550358864-518f202c02ba?w=800&q=80","https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80"}'::text[], '6%', '{"Ueno Zoo Tokyo","family zoo Japan","Tokyo with kids"}'::text[], '{"parent_story": {"title": "She pressed her face against the glass for 15 minutes", "excerpt": "Our daughter didn''t blink for 15 minutes watching the giant panda eat bamboo. I''ve never seen her that still. Ueno Zoo isn''t fancy, but it''s the most honest, wonderful zoo we''ve ever been to.", "author": "James, dad of 1 from London", "fullStory": "We almost skipped Ueno Zoo for the more famous Asahiyama. So glad we didn''t. The panda exhibit is up close \u2014 like, 2 feet away through glass. Our 5-year-old pressed her face against it and watched for 15 minutes without moving. The zoo is old-school (no flashy signs or VR), but the animals look happy and well-cared for. That matters more than any gimmick."}, "itinerary_comparison": {"halfDay": "Zoo only, 2-3 hours, skip museums", "fullDay": "Zoo + National Museum + picnic in Ueno Park", "bestFor": "Ages 0-8, animal lovers, budget travelers"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('tokyo-003', 'KidZania Tokyo', 'Tokyo', 'Japan', 'Theme Parks', 'A kid-sized city where children can try 100+ real professions. From pilot to firefighter to surgeon, each activity teaches real skills through immersive role-play.', '4-14', 4.8, '$$', 89, 'Lalaport Toyosu, Tokyo', 'Weekdays (weekends are packed)', 'https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80', '{"Educational Programs","Role-playing Activities","Language Support","Indoor Facility"}'::text[], '{"Supervised Activities","Child Tracking System","Emergency Protocols","Staff in Every Zone"}'::text[], '{"Book the first session (9 AM-3 PM). The afternoon session is more crowded and activities run out.","Let your kid choose their own path. We tried to ''optimize'' our son''s schedule and he rebelled. Letting him pick doubled his engagement.","The firefighting activity is the most popular — line up 15 minutes before it starts or you''ll wait 45+ minutes.","They speak English at most activities. Don''t worry about the Japanese language barrier.","Bring a small backpack for all the ''paychecks'' and souvenirs they''ll collect. You''ll thank me later."}'::text[], '{"https://images.unsplash.com/photo-1776619455134-1c4f2f1422cb?w=800&q=80","https://images.unsplash.com/photo-1590559899731-a382839e5549?w=800&q=80","https://images.unsplash.com/photo-1716745324526-8a4149760198?w=800&q=80"}'::text[], '7%', '{"KidZania Tokyo","kids role play Tokyo","educational activities Japan"}'::text[], '{"parent_story": {"title": "He came home and asked if he could be ALL of them", "excerpt": "He was a firefighter for 45 minutes. Then a pilot. Then a surgeon. He came home and asked if he could do ALL of them when he grows up. We said yes, buddy. You can do anything.", "author": "Lisa, mom of 1 from Singapore", "fullStory": "KidZania was the highlight of our Tokyo trip \u2014 and we did Disneyland. My 7-year-old son tried 8 professions in one day. The best part? Each activity is 20-30 minutes, so they actually complete something. He learned more about career possibilities in one day than in a year of school."}, "itinerary_comparison": {"halfDay": "4-5 activities, best for ages 4-8", "fullDay": "8-10 activities, worth it for ages 6-14", "bestFor": "Curious kids who love role-play"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('tokyo-004', 'teamLab Borderless', 'Tokyo', 'Japan', 'Museums', 'An immersive digital art museum where art flows out of rooms and interacts with visitors. Kids run through projected waterfalls, step on flowers that bloom, and explore endless mirror rooms.', '4-99', 4.6, '$$', 93, 'Azabudai Hills, Tokyo', 'Weekdays, right at opening', 'https://images.unsplash.com/photo-1737133976215-0b3c272e7c2d?w=800&q=80', '{"Wheelchair Accessible","Locker Storage","Cafe","Gift Shop"}'::text[], '{"Soft Flooring","Staff Everywhere","Emergency Exits Marked","No Sharp Edges"}'::text[], '{"Wear white or light-colored clothes. The digital projections reflect off white fabric and make amazing photos.","The ''Crystal Universe'' room is the most Instagrammable, but kids love the ''Sketch Ocean'' where their drawings come to life.","Go early (10 AM opening). By noon it''s packed and the magic dims with crowds.","Babies in carriers are fine but toddlers might get overwhelmed by the dark rooms. Bring a comfort item.","Don''t rush. There are no wrong paths — let your kids lead and you''ll discover hidden rooms."}'::text[], '{"https://images.unsplash.com/photo-1716745324526-8a4149760198?w=800&q=80","https://images.unsplash.com/photo-1738023354227-16a406891bd2?w=800&q=80","https://images.unsplash.com/photo-1735796788543-c99c460a0800?w=800&q=80"}'::text[], '5%', '{"teamLab Tokyo","digital art museum kids","interactive museum Japan"}'::text[], '{"parent_story": {"title": "My daughter drew a fish and it swam away from her", "excerpt": "She colored a fish on the provided paper, scanned it, and watched it swim across the wall. She screamed with joy. Then drew 7 more. We were there for 3 hours.", "author": "Tom, dad of 2 from Sydney", "fullStory": "The Sketch Ocean exhibit alone is worth the entry price. Each kid gets a piece of paper, colors their fish or jellyfish, and watches it appear on a massive digital aquarium. The best part? Their creation swims with everyone else''s. My 6-year-old spent an hour just watching her fish interact with strangers'' fish."}, "itinerary_comparison": {"halfDay": "2 hours, enough for main exhibits", "fullDay": "4-5 hours with cafe break, see everything", "bestFor": "Creative kids, teens, parents who love photography"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('bangkok-001', 'Safari World Bangkok', 'Bangkok', 'Thailand', 'Zoos & Aquariums', 'Thailand''s largest drive-through safari with over 8,000 animals. Feed giraffes from your car window, watch dolphin shows, and explore the marine park.', '2-10', 4.5, '$$', 85, '99 Panya Indra Rd, Bangkok', 'Morning (animals most active)', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80', '{"Drive-through Safari","Animal Shows","Restaurants","Gift Shops"}'::text[], '{"Animal Barriers","Trained Guides","First Aid","Emergency Procedures"}'::text[], '{"Bring bananas and carrots in your car. Yes, you can feed the animals from your window and it''s the best part.","The marine park shows have limited seating. Arrive 20 minutes early for dolphin show.","Skip the restaurant inside — the food is overpriced and mediocre. Pack lunch or eat after.","Rent a car or hire a driver. Taxis are hard to find on the way back.","The jungle walk section is hot and humid. Bring water and a handheld fan."}'::text[], '{"https://images.unsplash.com/photo-1550358864-518f202c02ba?w=800&q=80","https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80","https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80"}'::text[], '6%', '{"Safari World Bangkok","family Bangkok","kids Bangkok zoo"}'::text[], '{"parent_story": {"title": "A giraffe ate our map through the car window", "excerpt": "My son left the window half-open and a giraffe grabbed our map. He laughed so hard he cried. Worth every baht just for that memory.", "author": "Emma, mom of 2 from London", "fullStory": "Safari World is chaotic, a bit run-down, and absolutely wonderful. The drive-through section is the highlight \u2014 animals come right up to your car. Our 5-year-old fed a zebra from his hand. The giraffe feeding platform lets you get face-to-face. It''s not a ''nice'' zoo, but it''s an unforgettable experience for kids."}, "itinerary_comparison": {"halfDay": "Drive-through safari + dolphin show", "fullDay": "Full safari + marine park + all shows", "bestFor": "Ages 2-10, animal lovers"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('bangkok-002', 'KidZania Bangkok', 'Bangkok', 'Thailand', 'Theme Parks', 'Same world-class concept as Tokyo''s KidZania — a kid-sized city with 80+ professions. English-friendly with many international brands participating.', '4-14', 4.6, '$$', 80, 'Siam Paragon, Bangkok', 'Weekdays, opening time', 'https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80', '{"Indoor","Educational","Cafe","Parent Lounge"}'::text[], '{"Supervised","Child Tracking","English Speaking Staff"}'::text[], '{"Buy tickets online in advance. Walk-in prices are 30% higher and sessions sell out.","The Siam Paragon location is perfect — you can drop kids and shop for 2 hours in the mall.","English is widely spoken. Don''t worry if your kids don''t speak Thai.","The pilot and journalist activities are the most popular. Go there first.","Air conditioning is excellent. Bring a light jacket for kids."}'::text[], '{"https://images.unsplash.com/photo-1590559899731-a382839e5549?w=800&q=80","https://images.unsplash.com/photo-1738023354227-16a406891bd2?w=800&q=80","https://images.unsplash.com/photo-1716745324526-8a4149760198?w=800&q=80"}'::text[], '7%', '{"KidZania Bangkok","Siam Paragon kids","Bangkok indoor activities"}'::text[], '{"parent_story": {"title": "We dropped her off and she didn''t look back", "excerpt": "Our shy 6-year-old walked into KidZania and transformed into a confident little professional. She ran the news desk, flew a plane, and put out a fire. We barely saw her for 4 hours.", "author": "Mike, dad of 1 from New York", "fullStory": "KidZania Bangkok at Siam Paragon is a lifesaver for parents who need a break. The kids are so engaged they don''t notice you''re gone. The staff are excellent with English-speaking children. Our daughter made friends with a local Thai girl through the shared activities \u2014 language barrier didn''t matter."}, "itinerary_comparison": {"halfDay": "4-5 activities, 3 hours", "fullDay": "8-10 activities, 5-6 hours with lunch break", "bestFor": "Ages 4-10, families who want a break in AC"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('bangkok-003', 'Siam Ocean World', 'Bangkok', 'Thailand', 'Zoos & Aquariums', 'One of Southeast Asia''s largest aquariums, located in the basement of Siam Paragon. Walk through an underwater tunnel surrounded by sharks, rays, and thousands of tropical fish.', '2-12', 4.7, '$$', 82, 'Siam Paragon, Bangkok', 'Weekday mornings', 'https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80', '{"Underwater Tunnel","Touch Pool","Glass-bottom Boat","Cafe"}'::text[], '{"Glass Barriers","Lifeguards","Emergency Exits","First Aid"}'::text[], '{"The glass-bottom boat ride is worth the extra 200 baht. Kids love seeing sharks swim beneath their feet.","Go at opening time (10 AM). By 11 AM the school groups arrive and it gets loud.","The touch pool lets kids pet starfish and sea cucumbers. Bring hand sanitizer.","Combine with KidZania (same mall) for a full-day indoor activity.","The penguin exhibit is the coldest room. Bring a light jacket for little ones."}'::text[], '{"https://images.unsplash.com/photo-1517411032315-54ef2cb783bb?w=800&q=80","https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80","https://images.unsplash.com/photo-1590559899731-a382839e5549?w=800&q=80"}'::text[], '5%', '{"Siam Ocean World","Bangkok aquarium","indoor kids Bangkok"}'::text[], '{"parent_story": {"title": "The shark swam right over his head", "excerpt": "Walking through the underwater tunnel, a 3-meter shark passed directly over our 4-year-old''s head. His eyes went wide. He whispered ''Mama, did you see that?'' Six times. We stood there for 20 minutes.", "author": "Anna, mom of 1 from Hong Kong", "fullStory": "Siam Ocean World is surprisingly impressive for a mall basement aquarium. The underwater tunnel is the highlight \u2014 it''s long enough that you don''t feel rushed. The shark diversity is excellent. Our son still talks about the ''big fish that flew over us.''"}, "itinerary_comparison": {"halfDay": "2-3 hours, see all exhibits", "fullDay": "3-4 hours with glass-bottom boat and touch pool", "bestFor": "Ages 2-10, rainy days, AC relief"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('singapore-001', 'Gardens by the Bay', 'Singapore', 'Singapore', 'Parks & Nature', 'Futuristic gardens with giant Supertrees, two massive conservatories, and the nightly Garden Rhapsody light and sound show. A must-visit for families.', '0-99', 4.8, '$$', 95, '18 Marina Gardens Dr, Singapore', 'Evening (light show at 7:45 PM)', 'https://images.unsplash.com/photo-1560580652-cd41f0dcc565?w=800&q=80', '{"Wheelchair Accessible","Stroller Rental","Nursing Rooms","Restaurants"}'::text[], '{"Well-lit Paths","Security Guards","First Aid Stations","Emergency Phones"}'::text[], '{"The OCBC Skyway (walkway between Supertrees) closes at 8 PM. Do it BEFORE the light show, not after.","Bring a picnic blanket. The best spot for the light show is on the grass directly under the tallest Supertrees.","The Cloud Forest dome is freezing (18°C). Bring a jacket for kids — yes, in Singapore.","Avoid Saturday nights. The crowds are 3x larger and the magic diminishes.","The children''s garden has a splash pad. Bring swimsuits and towels."}'::text[], '{"https://images.unsplash.com/photo-1485257334450-84ec1ba6393d?w=800&q=80","https://images.unsplash.com/photo-1775152496490-9cebc8bb7dde?w=800&q=80","https://images.unsplash.com/photo-1508597370841-836e72ef6f54?w=800&q=80"}'::text[], '4%', '{"Gardens by the Bay","Singapore family","kids Singapore"}'::text[], '{"parent_story": {"title": "We almost missed the light show because of the splash pad", "excerpt": "The children''s garden splash pad is so good our kids refused to leave. We bribed them with ice cream to get to the Supertree show. Worth it \u2014 but plan an extra 30 minutes for the water play.", "author": "Chris, dad of 2 from Sydney", "fullStory": "Gardens by the Bay is incredible but the Far East Organization Children''s Garden is the secret weapon. A massive water play area with spraying arches, buckets that dump water, and a treehouse. It''s free. Our kids spent 2 hours there. We had to drag them away for the light show."}, "itinerary_comparison": {"halfDay": "Cloud Forest + Flower Dome + OCBC Skyway", "fullDay": "Add Children''s Garden splash pad + light show + dinner", "bestFor": "All ages, especially 0-10 for splash pad"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('singapore-002', 'Singapore Zoo & Night Safari', 'Singapore', 'Singapore', 'Zoos & Aquariums', 'World-famous open-concept zoo where animals roam in naturalistic habitats without visible barriers. Combine with the Night Safari for a full-day animal adventure.', '1-12', 4.6, '$$', 92, '80 Mandai Lake Rd, Singapore', 'Morning (zoo), Evening (Night Safari)', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80', '{"Breakfast with Orangutans","Tram Ride","Splash Zone","Restaurants"}'::text[], '{"Natural Barriers","Trained Staff","First Aid","Security"}'::text[], '{"Book ''Breakfast with Orangutans'' in advance. It sells out weeks ahead and is worth every cent.","The zoo opens at 8:30 AM. Arrive then — by 10 AM the animals are sleepy and the crowds arrive.","The tram is great for tired legs. Hop on and off throughout the day.","The Night Safari is separate (different park, different ticket). It starts at 7:15 PM.","The splash zone near the elephant exhibit is perfect for hot days. Bring a change of clothes."}'::text[], '{"https://images.unsplash.com/photo-1658511126414-898f14abce56?w=800&q=80","https://images.unsplash.com/photo-1550358864-518f202c02ba?w=800&q=80","https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80"}'::text[], '5%', '{"Singapore Zoo","Night Safari","family Singapore"}'::text[], '{"parent_story": {"title": "An orangutan stole my croissant", "excerpt": "I was holding a croissant near the Breakfast with Orangutans area. One reached out, gently took it from my hand, and ate it in two bites. The keeper laughed and said ''That''s Ah Meng \u2014 she does this.'' Best photo of the trip.", "author": "Priya, mom of 2 from Mumbai", "fullStory": "Breakfast with Orangutans is not a gimmick \u2014 it''s genuinely magical. You sit at tables near the orangutan platform, and they come down to interact. They''re gentle, curious, and incredibly expressive. My 8-year-old fed one a banana and cried happy tears."}, "itinerary_comparison": {"halfDay": "Zoo only, 3-4 hours", "fullDay": "Zoo + River Wonders + Night Safari", "bestFor": "Ages 2-12, animal enthusiasts"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('singapore-003', 'Sentosa Island', 'Singapore', 'Singapore', 'Theme Parks', 'Singapore''s island resort with Universal Studios, SEA Aquarium, Adventure Cove Waterpark, beaches, and more. A full-day (or multi-day) family destination.', '2-17', 4.5, '$$$', 90, 'Sentosa Island, Singapore', 'Weekdays (weekends very crowded)', 'https://images.unsplash.com/photo-1644327981167-fbd67b34ba72?w=800&q=80', '{"Beaches","Theme Parks","Restaurants","Hotels","Monorail"}'::text[], '{"Lifeguards","Security","First Aid","Lost Child Centers"}'::text[], '{"Buy the Sentosa Fun Pass online — it bundles attractions and saves 20-30%.","Universal Studios is best for ages 7+. For younger kids, skip it and go to SEA Aquarium + waterpark.","The beach at Palawan is the most kid-friendly — calm water, soft sand, and a pirate ship playground.","Eat at the Sentosa Food Village (Hawker Chan) — Michelin-starred chicken rice for $5, not $50.","The monorail is free for Sentosa hotel guests and kids under 3."}'::text[], '{"https://images.unsplash.com/photo-1647592720834-ffe28f6ddf75?w=800&q=80","https://images.unsplash.com/photo-1573558290253-fde4fa372d80?w=800&q=80","https://images.unsplash.com/photo-1513889961551-628c1e5e2ee9?w=800&q=80"}'::text[], '6%', '{"Sentosa Island","Universal Studios Singapore","family Singapore"}'::text[], '{"parent_story": {"title": "Universal Studios with a 5-year-old: a survival guide", "excerpt": "We bought the Express Pass and it saved our trip. She rode the flying dinosaur 4 times. She''s 5. I don''t know where she gets the energy, but I know where she gets the courage \u2014 Super Nintendo World.", "author": "Lisa, mom of 1 from Manila", "fullStory": "Sentosa is overwhelming in the best way. Universal Studios was our focus \u2014 the Express Pass is expensive but essential. Our daughter, who''s scared of everything, loved Battlestar Galactica. The waterpark was the perfect afternoon cool-down after the morning theme park intensity."}, "itinerary_comparison": {"halfDay": "One attraction (Universal or SEA Aquarium)", "fullDay": "2 attractions + beach + lunch", "bestFor": "Families wanting variety, ages 5+"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('hongkong-001', 'Hong Kong Disneyland', 'Hong Kong', 'Hong Kong', 'Theme Parks', 'The smallest Disney park but packed with unique charm. Exclusive attractions like Mystic Manor and the only Marvel Avengers Campus in Asia make it a must-visit for families.', '3-12', 4.8, '$$$', 94, 'Lantau Island, Hong Kong', 'Weekdays, November-February', 'https://images.unsplash.com/photo-1737040009019-1576b1342b0e?w=800&q=80', '{"Stroller Rental","Baby Care Centers","Family Restrooms","Height Restrictions","First Aid"}'::text[], '{"Trained Staff","Emergency Protocols","Lost Child Centers","Allergy-Friendly Options"}'::text[], '{"Use the ''Priority Pass'' on the Disney app — it''s free and saves 30-45 minutes per ride on busy days.","The park is small enough to do in one day without rushing. Don''t feel pressured to arrive at rope drop.","Mystic Manor is exclusive to Hong Kong Disneyland and better than Haunted Mansion. Don''t skip it.","The Marvel Avengers Campus gets hot. Bring hats and go indoors to the Ant-Man ride for AC.","Eat at the Explorer''s Club restaurant — themed rooms, good food, and Mickey Mouse-shaped waffles."}'::text[], '{"https://images.unsplash.com/photo-1718863336605-5e9c7c738336?w=800&q=80","https://images.unsplash.com/photo-1642262978329-a9211480300b?w=800&q=80","https://images.unsplash.com/photo-1718863336803-0a3b1f33840b?w=800&q=80"}'::text[], '7%', '{"Hong Kong Disneyland","family Hong Kong","Disneyland Asia"}'::text[], '{"parent_story": {"title": "She met Elsa and forgot we existed", "excerpt": "Our Frozen-obsessed 4-year-old met Elsa at the Royal Academy. She froze, then cried happy tears, then talked about it for the entire 3-hour flight home. Worth every dollar.", "author": "Rebecca, mom of 1 from Manila", "fullStory": "Hong Kong Disneyland is small but perfectly formed. We did the whole park in 8 hours with a 4-year-old, including a 2-hour lunch break. The Mystic Manor ride is genuinely impressive \u2014 even adults will love it. The castle is smaller than Tokyo''s but the intimacy makes it special."}, "itinerary_comparison": {"halfDay": "Main Street + Fantasyland + Mystic Manor + lunch", "fullDay": "All lands, both shows, fireworks, dinner at Explorer''s Club", "bestFor": "Ages 3-10, Disney fans, Marvel fans"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('hongkong-002', 'Ocean Park Hong Kong', 'Hong Kong', 'Hong Kong', 'Theme Parks', 'A unique blend of aquarium, animal park, and thrill rides perched on a mountainside. Giant pandas, dolphin shows, and the iconic hair-raising cable car ride across the bay.', '2-17', 4.7, '$$', 88, 'Wong Chuk Hang, Hong Kong Island', 'Weekdays, September-November', 'https://images.unsplash.com/photo-1612276036430-e7240b151bd0?w=800&q=80', '{"Stroller Access","Nursing Rooms","Cable Car","Restaurants","Aquarium"}'::text[], '{"Animal Safety Barriers","First Aid Stations","Trained Staff","Emergency Protocols"}'::text[], '{"Take the cable car to the summit for the view, then the Ocean Express train back down — kids love the underwater-themed tunnel ride.","The panda exhibit is indoors and air-conditioned. Go during the hottest part of the day (1-3 PM) to escape the heat.","The Grand Aquarium has a massive 13-meter viewing panel. Visit at feeding time (check schedule) for the full experience.","Download the Ocean Park app to check ride wait times and show schedules in real time.","Bring a light jacket — the cable car and summit areas get windy even on hot days."}'::text[], '{"https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80","https://images.unsplash.com/photo-1517411032315-54ef2cb783bb?w=800&q=80","https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80"}'::text[], '6%', '{"Ocean Park Hong Kong","family attractions Hong Kong","Hong Kong aquarium"}'::text[], '{"parent_story": {"title": "The cable car ride that cured our fear of heights", "excerpt": "Our 6-year-old was terrified of the cable car. By the end of the 10-minute ride across the bay, she was pressing her face against the glass asking to do it again. The pandas were a bonus.", "author": "David, dad of 2 from Sydney", "fullStory": "Ocean Park is half amusement park, half world-class zoo. The cable car is the highlight \u2014 it glides over the ocean with stunning views of the South China Sea. The Grand Aquarium''s 400 species kept our kids mesmerized for an hour. The thrill rides at the summit are legitimately fun for teens too."}, "itinerary_comparison": {"halfDay": "Cable car + Grand Aquarium + pandas + lunch", "fullDay": "All exhibits + 3-4 thrill rides + dolphin show + cable car sunset", "bestFor": "Ages 3-17, animal lovers, thrill seekers"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('hongkong-003', 'Ngong Ping 360 & Tian Tan Buddha', 'Hong Kong', 'Hong Kong', 'Parks & Nature', 'A breathtaking 25-minute cable car ride over Lantau Island leading to the massive Tian Tan Buddha statue. The crystal-clear floor cabins make you feel like you''re flying above the mountains.', '4-17', 4.6, '$$', 85, 'Tung Chung, Lantau Island, Hong Kong', 'Clear days, morning (9-11 AM)', 'https://images.unsplash.com/photo-1644327981167-fbd67b34ba72?w=800&q=80', '{"Cable Car","Restaurants","Gift Shops","Temple","Walking Paths"}'::text[], '{"Regular Cable Car Inspections","Staff at Both Stations","Clear Safety Instructions","First Aid"}'::text[], '{"Book the Crystal Cabin (glass floor) online in advance — standard cabins have shorter lines but the glass floor is worth it for the photos.","Go on a clear day. The cable car is cancelled in heavy fog and the view is the whole point.","Climbing the 268 steps to the Buddha is a workout for little legs. Bring water and take breaks.","The Ngong Ping Village has a decent 360-degree cinema show about Lantau. Kids enjoy it and it''s a good rest stop.","Combine with Hong Kong Disneyland for a full Lantau Island day — they''re on the same island and 15 minutes apart by taxi."}'::text[], '{"https://images.unsplash.com/photo-1594103345324-16aa1bcffdb9?w=800&q=80","https://images.unsplash.com/photo-1776619455134-1c4f2f1422cb?w=800&q=80","https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80"}'::text[], '5%', '{"Ngong Ping 360","Tian Tan Buddha","Hong Kong cable car"}'::text[], '{"parent_story": {"title": "The glass floor made us feel like superheroes", "excerpt": "Our twins (age 6) spent the entire cable car ride lying on the glass floor, giggling and pointing at the trees below. My wife held my hand and said ''This is the best decision we made.'' She was right.", "author": "Tom, dad of twins from Melbourne", "fullStory": "The Ngong Ping 360 cable car is genuinely spectacular \u2014 25 minutes over mountains and ocean. The Buddha statue at the top is impressive, but the journey there is the real magic for kids. The Po Lin Monastery has a vegetarian restaurant that''s surprisingly kid-friendly with noodles and dim sum."}, "itinerary_comparison": {"halfDay": "Cable car up + Buddha + monastery lunch + cable car down", "fullDay": "Add Ngong Ping Village + Tai O fishing village + Disneyland", "bestFor": "Ages 5+, adventure families, culture lovers"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('phuket-001', 'Phuket Elephant Sanctuary', 'Phuket', 'Thailand', 'Zoos & Aquariums', 'An ethical elephant sanctuary where families can observe rescued elephants in a natural habitat. No riding, no chains — just watching, feeding, and learning about these gentle giants.', '5-17', 4.9, '$$', 90, 'Paklok, Phuket, Thailand', 'Morning session (8 AM-12 PM)', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80', '{"Feeding Platform","Educational Center","Changing Rooms","Cafe","Souvenir Shop"}'::text[], '{"Professional Guides","Safety Briefing","Clear Boundaries","First Aid Trained Staff"}'::text[], '{"Book the morning session — elephants are most active before noon and the afternoon heat makes them sleepy.","Wear mud-friendly clothes. You''ll be making mud balls to feed the elephants and it gets messy.","No riding here. If a sanctuary offers elephant riding, it''s not ethical. This place is the real deal.","The minimum age is 5 for the full tour. Younger kids can visit but won''t get the full interaction.","Bring insect repellent and sunscreen. The sanctuary is in a rural area with mosquitoes."}'::text[], '{"https://images.unsplash.com/photo-1737133976215-0b3c272e7c2d?w=800&q=80","https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80","https://images.unsplash.com/photo-1550358864-518f202c02ba?w=800&q=80"}'::text[], '8%', '{"Phuket Elephant Sanctuary","ethical elephant Thailand","Phuket family"}'::text[], '{"parent_story": {"title": "Feeding an elephant is surprisingly terrifying and beautiful", "excerpt": "My 7-year-old held out a bunch of bananas and a 4-ton elephant gently took it with her trunk. She laughed so hard she snorted. Best $80 we spent in Thailand.", "author": "Emma, mom of 1 from London", "fullStory": "Phuket Elephant Sanctuary is the gold standard for ethical animal tourism. They rescued 11 elephants from logging and riding camps. Our guide explained each elephant''s story \u2014 heartbreaking but the happy ending made it worth it. No riding, no hooks, just respect. My kids learned more about animal welfare here than in any classroom."}, "itinerary_comparison": {"halfDay": "Morning tour: feeding + mud bath + river walk + lunch", "fullDay": "Morning tour only (afternoon rest is elephant downtime)", "bestFor": "Ages 5+, animal lovers, ethical tourism fans"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('phuket-002', 'Splash Jungle Water Park', 'Phuket', 'Thailand', 'Theme Parks', 'Phuket''s largest water park with thrilling slides, a massive lazy river, kids'' splash zone, and the famous Boomerango slide. Perfect for a hot day escape.', '3-17', 4.5, '$$', 83, 'Kathu, Phuket, Thailand', 'Weekday mornings (opens 10 AM)', 'https://images.unsplash.com/photo-1550358864-518f202c02ba?w=800&q=80', '{"Kids Splash Zone","Lazy River","Wave Pool","Cabanas","Restaurants","Locker Rental"}'::text[], '{"Lifeguards at Every Slide","Depth Markings","Height Restrictions","First Aid Room","Life Jackets Available"}'::text[], '{"Rent a cabana for the day. It''s $40 extra but worth it for the shaded area, fan, and safe spot for your bags.","Bring waterproof phone pouches. There''s no dry storage on the slides and the lockers are small.","The Boomerango slide has a height minimum of 122 cm. Measure your kid before queuing or face disappointment.","Eat at the park restaurant — the prices are reasonable by Phuket standards ($5-8 per meal).","Go on a weekday. Weekends are packed with locals and wait times hit 30+ minutes per slide."}'::text[], '{"https://images.unsplash.com/photo-1776619455134-1c4f2f1422cb?w=800&q=80","https://images.unsplash.com/photo-1590559899731-a382839e5549?w=800&q=80","https://images.unsplash.com/photo-1738023354227-16a406891bd2?w=800&q=80"}'::text[], '5%', '{"Splash Jungle Phuket","Phuket water park","family Phuket"}'::text[], '{"parent_story": {"title": "My 4-year-old spent 2 hours in the splash zone and called it a perfect day", "excerpt": "She was too short for most slides but the kids'' splash zone had a mini water fortress with spraying guns and a tipping bucket. We didn''t see another slide all day and she was still exhausted by 3 PM.", "author": "James, dad of 1 from Auckland", "fullStory": "Splash Jungle is well-maintained and the staff are constantly monitoring safety. The lazy river is a winner for the whole family \u2014 you float past mini waterfalls and under bridges. The food is decent (pad thai and chicken nuggets for picky eaters). We spent 5 hours here and our only complaint was that we didn''t arrive earlier."}, "itinerary_comparison": {"halfDay": "10 AM - 2 PM: splash zone + 2-3 slides + lunch", "fullDay": "10 AM - 5 PM: all slides + lazy river + wave pool + cabana rest", "bestFor": "Ages 3-15, hot days, water lovers"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('bali-001', 'Bali Safari & Marine Park', 'Bali', 'Indonesia', 'Zoos & Aquariums', 'A 40-hectare wildlife park with over 100 species in natural habitats. Take a safari tram through open enclosures, watch elephant shows, and stay overnight at the animal-themed lodge.', '2-12', 4.6, '$$', 86, 'Gianyar, Bali, Indonesia', 'Morning (park opens at 9 AM)', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80', '{"Safari Tram","Animal Shows","Water Park","Restaurants","Hotel","Baby Changing Rooms"}'::text[], '{"Safari Vehicle Barriers","Trained Keepers","First Aid Stations","Emergency Evacuation Plan"}'::text[], '{"Book the Safari Journey (tram) first thing — the animals are most active and the lines shortest before 11 AM.","The night safari and fire dinner show are surprisingly good. Stay overnight if your budget allows.","Bring a change of clothes — the kids'' splash park is part of the admission and your kids WILL want to swim.","The on-site Tsavo Lion Restaurant lets you eat while lions roam outside the glass. Reserve a window table.","Sunscreen and hats are essential. Much of the park is open-air with limited shade."}'::text[], '{"https://images.unsplash.com/photo-1550358864-518f202c02ba?w=800&q=80","https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80","https://images.unsplash.com/photo-1724892053773-cd28a4f6a622?w=800&q=80"}'::text[], '7%', '{"Bali Safari","Bali family","Bali with kids"}'::text[], '{"parent_story": {"title": "Eating lunch while a lion stared at us through the glass", "excerpt": "Our son nearly dropped his chicken nugget when a lion yawned 2 feet from his face through the restaurant window. He whispered ''Is he going to eat me?'' The waiter said ''Only if you don''t finish your vegetables.'' Best restaurant experience of the trip.", "author": "Sarah, mom of 2 from Singapore", "fullStory": "Bali Safari Park exceeded our expectations. The tram ride through the open enclosures is impressive \u2014 you get remarkably close to tigers, lions, and zebras. The elephant show was educational without feeling exploitative. We stayed at the Mara River Safari Lodge and woke up to animals wandering past our balcony. Magical for the kids."}, "itinerary_comparison": {"halfDay": "Safari tram + 2 shows + lunch", "fullDay": "Safari tram + all shows + water park + Tsavo dinner", "bestFor": "Ages 2-12, animal lovers, overnight adventurers"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('bali-002', 'Waterbom Bali', 'Bali', 'Indonesia', 'Theme Parks', 'Asia''s best water park consistently ranked in the world''s top 10. Lush tropical gardens, 26 world-class slides, FlowRider surfing, and a dedicated kids'' area that''s pure paradise.', '3-17', 4.8, '$$', 93, 'Kuta, Bali, Indonesia', 'Weekday mornings (opens 9 AM)', 'https://images.unsplash.com/photo-1550358864-518f202c02ba?w=800&q=80', '{"Kids Play Area","FlowRider","Lazy River","Swim-up Bar","Restaurants","Lockers","Towels Included"}'::text[], '{"Lifeguards at Every Slide","Height/Weight Requirements","Life Jackets Provided","First Aid Clinic","Well-maintained Equipment"}'::text[], '{"Book tickets online in advance — you skip the massive queue at the entrance and save 15%.","Rent an umbrella bed for the day ($15). Kuta sun is brutal and you''ll need the shade for little ones.","The FlowRider surfing simulator is included in admission. Kids 6+ can try it — staff are excellent with beginners.","The Lazy River is a lifesaver for tired parents. Float around for 30 minutes of blissful silence.","Bring reef-safe sunscreen. The park enforces this for their water filtration and the local stores sell it."}'::text[], '{"https://images.unsplash.com/photo-1775152496490-9cebc8bb7dde?w=800&q=80","https://images.unsplash.com/photo-1590559899731-a382839e5549?w=800&q=80","https://images.unsplash.com/photo-1735796788543-c99c460a0800?w=800&q=80"}'::text[], '6%', '{"Waterbom Bali","Bali water park","best water park Asia"}'::text[], '{"parent_story": {"title": "The 4-year-old who conquered the biggest slide", "excerpt": "Our daredevil 4-year-old insisted on riding the Super Bowl. The lifeguard looked at us like ''are you sure?'' We strapped her in. She came out screaming \u2014 with joy. She wanted to go again. We didn''t. But she won.", "author": "Mark, dad of 2 from Perth", "fullStory": "Waterbom is the best-managed water park I''ve ever visited. Clean, safe, stunningly landscaped \u2014 it feels like a tropical resort with waterslides. The kids'' area ''Funtastic'' has mini versions of the big slides, so even toddlers feel like they''re conquering something. My 8-year-old spent 3 hours on the Python slide alone."}, "itinerary_comparison": {"halfDay": "Morning session: kids area + 4-5 slides + lazy river", "fullDay": "9 AM - 5 PM: all slides + FlowRider + lunch + cabana rest", "bestFor": "Ages 3-17, all-day fun, Bali bucket list"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('bali-003', 'Bali Treetop Adventure Park', 'Bali', 'Indonesia', 'Parks & Nature', 'An aerial adventure park set in the botanical gardens of Bedugul. Seven courses of zip lines, rope bridges, and Tarzan swings nestled among 400-year-old trees in the cool highlands.', '4-17', 4.7, '$', 80, 'Bedugul Botanical Garden, Bali, Indonesia', 'Morning (cooler weather, less fog)', 'https://images.unsplash.com/photo-1599387433955-63ea3540497d?w=800&q=80', '{"Multiple Difficulty Courses","Harness System","Picnic Areas","Cafe","Botanical Garden Access"}'::text[], '{"Continuous Safety Line System","Trained Guides","Full Harness & Helmet","Regular Equipment Inspection","Safety Briefing Required"}'::text[], '{"The Bedugul area is 600m above sea level and much cooler than the coast. Bring a light jacket — you''ll actually need it.","Start with the yellow (easy) course if your kids are under 8. The black (expert) course requires serious upper body strength.","Wear closed-toe shoes with good grip. Flip-flops are not allowed and they don''t rent shoes.","Combine with the Bedugul Botanical Garden and Ulun Danu Beratan Temple for a full day in the highlands.","The drive from Kuta/Seminyak takes 1.5-2 hours. Leave by 7 AM to avoid traffic."}'::text[], '{"https://images.unsplash.com/photo-1485257334450-84ec1ba6393d?w=800&q=80","https://images.unsplash.com/photo-1508597370841-836e72ef6f54?w=800&q=80","https://images.unsplash.com/photo-1560580652-cd41f0dcc565?w=800&q=80"}'::text[], '5%', '{"Bali Treetop Adventure","Bali adventure park","family Bali activities"}'::text[], '{"parent_story": {"title": "My 6-year-old Tarzan conquered all 7 courses", "excerpt": "She was scared on the first platform. Then she did the zip line and something clicked. She finished all 7 courses, came down, and asked to go again. I''ve never seen her more proud of herself.", "author": "Anna, mom of 1 from Hong Kong", "fullStory": "Bali Treetop Adventure Park is a hidden gem. The continuous safety line system means kids can''t unclip themselves \u2014 as a safety-conscious parent, that gave me peace of mind. The courses range from easy (1m high, simple bridges) to expert (20m high, wobbly logs). Set in the lush Bedugul Botanical Gardens, it''s a welcome cool escape from Bali''s coastal heat."}, "itinerary_comparison": {"halfDay": "2-3 courses + botanical garden walk + picnic", "fullDay": "All 7 courses + garden + Ulun Danu Temple + lunch in Bedugul", "bestFor": "Ages 5+, adventure families, nature lovers"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('hanoi-001', 'Thang Long Water Puppet Theatre', 'Hanoi', 'Vietnam', 'Museums', 'Vietnam''s unique water puppet tradition brought to life in a charming theatre. Wooden puppets dance on water while live musicians play traditional instruments — enchanting for all ages.', '3-17', 4.7, '$', 84, '57B Dinh Tien Hoang St, Hoan Kiem, Hanoi', 'Evening show (5 PM or 6:30 PM)', 'https://images.unsplash.com/photo-1590559899731-a382839e5549?w=800&q=80', '{"Indoor Theatre","Air Conditioning","Gift Shop","Nearby Restaurants"}'::text[], '{"Clear Exits","No Obstacles","Seated Performance"}'::text[], '{"Book tickets at least a day in advance. Walk-up tickets sell out quickly, especially for the English-friendly 5 PM show.","Sit in rows 3-6 for the best views. Row 1 gets splashed and row 10+ struggles to see the details.","The show is 50 minutes — perfect for kids'' attention spans. Any longer and they''d get wiggly.","The theatre is right next to Hoan Kiem Lake. Combine with a walk around the lake and ice cream at Kem Trang Tien.","The stories are in Vietnamese but the puppetry is universal. Kids don''t need to understand the language to love it."}'::text[], '{"https://images.unsplash.com/photo-1551918120-9739cb430c6d?w=800&q=80","https://images.unsplash.com/photo-1735796788543-c99c460a0800?w=800&q=80","https://images.unsplash.com/photo-1738023354227-16a406891bd2?w=800&q=80"}'::text[], '4%', '{"Water Puppet Hanoi","Thang Long Theatre","Hanoi family activities"}'::text[], '{"parent_story": {"title": "50 minutes of pure magic \u2014 no screens required", "excerpt": "My 5-year-old doesn''t sit still for anything. She sat mesmerized for the entire 50-minute water puppet show. The dragon breathing fire and smoke on water was her favorite. Mine too, honestly.", "author": "Claire, mom of 2 from Melbourne", "fullStory": "Thang Long Water Puppet Theatre is a must-do in Hanoi. The puppeteers stand waist-deep in water behind a screen, controlling wooden puppets with long rods. The live traditional orchestra adds so much atmosphere. At $5-8 per ticket, it''s the cheapest family activity in Hanoi and one of the most memorable."}, "itinerary_comparison": {"halfDay": "Water puppet show + Hoan Kiem Lake walk + ice cream", "fullDay": "Old Quarter walking tour + Water Puppet show + night market dinner", "bestFor": "Ages 3+, culture lovers, rainy day activity"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('hanoi-002', 'VinKE Times City', 'Hanoi', 'Vietnam', 'Theme Parks', 'A massive indoor edutainment complex in the Times City urban area. Role-play city for kids with 50+ careers, plus an amusement floor with rides, VR games, and a bowling alley.', '3-14', 4.5, '$$', 79, 'Times City Urban Area, Hai Ba Trung, Hanoi', 'Weekday mornings (weekends packed)', 'https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80', '{"Indoor Facility","Air Conditioning","Food Court","Role-play City","Arcade Games","Bowling Alley"}'::text[], '{"Staff in Every Zone","Child-Friendly Equipment","Indoor Security","First Aid Room","Video Surveillance"}'::text[], '{"The role-play section (VinKE City) is separate from the amusement floor. Buy the combo ticket if your kids want both.","Popular careers like firefighter and pilot have long queues. Go to those first, do quieter ones later.","The shopping mall has excellent food options. Eat at the food court for $2-3 per person.","Plan for 3-4 hours minimum. Kids get deeply absorbed in the role-play and won''t want to leave.","English is limited at some stations. Download Google Translate or point to picture menus."}'::text[], '{"https://images.unsplash.com/photo-1716745324526-8a4149760198?w=800&q=80","https://images.unsplash.com/photo-1590559899731-a382839e5549?w=800&q=80","https://images.unsplash.com/photo-1772550018808-ebbcc271726c?w=800&q=80"}'::text[], '6%', '{"VinKE Times City","Hanoi indoor activities","kids edutainment Hanoi"}'::text[], '{"parent_story": {"title": "She was a scientist for 30 minutes and a pilot for 20", "excerpt": "My 6-year-old daughter tried being a scientist, a pilot, and a firefighter in one afternoon. They gave her a ''diploma'' for each one. She slept with them under her pillow that night.", "author": "Linh, mom of 1 from Ho Chi Minh City", "fullStory": "VinKE Times City is Hanoi''s answer to KidZania and it''s fantastic. The role-play city has over 50 careers with realistic mini-equipment \u2014 the hospital has an actual dentist chair, the fire station has a mini truck with lights. The staff guide the kids through each activity in Vietnamese but the actions are universal. Perfect for a rainy Hanoi day."}, "itinerary_comparison": {"halfDay": "VinKE City role-play (4-5 careers) + lunch in mall", "fullDay": "Role-play city + amusement floor + bowling + dinner", "bestFor": "Ages 4-10, rainy days, indoor fun"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('seoul-001', 'Lotte World', 'Seoul', 'South Korea', 'Theme Parks', 'A massive indoor-outdoor theme park in the heart of Seoul. The indoor Adventure zone (Lotte World Adventure) is the world''s largest indoor theme park, with rides, parades, and ice skating — all under one roof. The outdoor Magic Island offers thrill rides with lake views.', '3-14', 4.7, '$$', 89, '240 Olympic-ro, Songpa-gu, Seoul, South Korea', 'Weekdays, especially Tue-Thu (weekends very crowded)', 'https://images.unsplash.com/photo-1775144113652-6592b3ebeb06?w=800&q=80', '{"Indoor Theme Park","Outdoor Rides","Ice Skating Rink","Parade & Performances","Shopping Mall Connected","Lotte World Tower Adjacent"}'::text[], '{"Height Restrictions Enforced","Trained Ride Operators","First Aid Stations","Lost Child Center","CCTV Coverage"}'::text[], '{"Buy the ''Magic Pass'' online — it''s a fast-pass system that saves 30-60 minutes per ride on busy days.","Start with the outdoor rides (Magic Island) in the morning when lines are short, move indoors by noon.","The ice skating rink is surprisingly cheap ($5 rental included). Great for cooling off in summer.","Food inside the park is overpriced. Eat at the connected Lotte World Mall food court instead.","Go on a weekday if possible. Weekend waits hit 90 minutes for popular rides like Gyro Drop.","Combine with Lotte World Tower for a full day — you can walk there through the mall."}'::text[], '{"https://images.unsplash.com/photo-1513889961551-628c1e5e2ee9?w=800&q=80","https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80","https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80"}'::text[], '6%', '{"Lotte World Seoul","indoor theme park Seoul","Seoul with kids"}'::text[], '{"parent_story": {"title": "The indoor park that saved our rainy Seoul day", "excerpt": "It poured all morning and we thought our day was ruined. Then we discovered Lotte World Adventure \u2014 5 floors of rides indoors. Our daughter rode the balloon ride 6 times. Best ''rainy day'' of the trip.", "author": "Priya, mom of 2 from Singapore", "fullStory": "Lotte World is two parks in one \u2014 a massive indoor section and an outdoor thrill park on an island. The indoor part is perfect for younger kids (3-7) with gentle rides, a carousel, and a kids'' play zone. The outdoor part has legit thrill rides for older kids and teens. The parade at 2 PM is impressive \u2014 elaborate floats and K-pop dancers. We spent 8 hours here and still didn''t do everything."}, "itinerary_comparison": {"halfDay": "Indoor Adventure zone only: 4-5 rides + parade + shopping", "fullDay": "Morning outdoor rides + afternoon indoor + parade + ice skating + dinner", "bestFor": "Ages 4-12 indoors, 8+ for outdoor thrill rides"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('seoul-002', 'Seoul Grand Park & Zoo', 'Seoul', 'South Korea', 'Zoos & Aquariums', 'Korea''s largest zoo set inside a sprawling 9-million-pyeong park. Home to over 3,000 animals from 300+ species, including a polar bear exhibit, tropical rainforest dome, and children''s petting zoo. Reachable via a scenic sky-rail ride.', '0-12', 4.6, '$', 82, '102 Daegongwongwangjang-ro, Gwacheon, Gyeonggi-do, South Korea', 'Spring & Fall mornings (opens 9 AM)', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80', '{"Sky-Rail Cable Car","Children''s Petting Zoo","Playgrounds","Elephant Ride","Picnic Areas","Restaurants"}'::text[], '{"Animal Safety Barriers","First Aid Stations","Security Patrols","Well-Marked Paths","Emergency Exits"}'::text[], '{"Take the ''Elephant Train'' from the main gate to the zoo entrance — it''s a long walk for little legs otherwise.","The sky-rail (cable car) is worth the extra $3. Kids love the view and it saves 20 minutes of walking.","Bring a picnic — the park has dozens of shaded grassy areas perfect for lunch breaks.","The Children''s Zoo lets kids feed goats and rabbits. Hand sanitizer stations are available.","Spring (April-May) is spectacular with cherry blossoms throughout the park."}'::text[], '{"https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80","https://images.unsplash.com/photo-1550358864-518f202c02ba?w=800&q=80","https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80"}'::text[], '5%', '{"Seoul Grand Park","Seoul Zoo","family Seoul Korea"}'::text[], '{"parent_story": {"title": "The polar bear made my son question everything", "excerpt": "My 5-year-old stared at the polar bear for 10 minutes, then asked ''Is he sad because ice is melting?'' We had the most important conversation of our trip right there. Kids notice everything.", "author": "Michael, dad of 1 from Sydney", "fullStory": "Seoul Grand Park is enormous \u2014 think Central Park with a world-class zoo in the middle. The polar bear exhibit is impressive and surprisingly thoughtful about conservation messaging. The children''s zoo section has a hands-on petting area that our kids loved. At $3 per adult entry, it''s absurdly good value. The nearby Seoul Museum of Art (within the park) has kids'' workshops on weekends."}, "itinerary_comparison": {"halfDay": "Sky-rail up + zoo main exhibits + children''s zoo + picnic", "fullDay": "Morning zoo + afternoon Seoul Museum of Art + botanical garden + playground", "bestFor": "Ages 1-10, budget travelers, nature families"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('seoul-003', 'COEX Aquarium', 'Seoul', 'South Korea', 'Zoos & Aquariums', 'One of Korea''s largest aquariums with over 40,000 marine creatures across 17 themed zones. Walk through an 85-meter underwater tunnel surrounded by sharks and rays, touch starfish in the interactive zone, and see the rare Komodo dragon.', '2-12', 4.7, '$$', 85, '513 Yeongdong-daero, Gangnam-gu, Seoul, South Korea', 'Weekday mornings (opens 10 AM)', 'https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80', '{"Underwater Tunnel","Touch Pool","Interactive Exhibits","Gift Shop","Cafe","Stroller Access"}'::text[], '{"Glass Barriers","Staff at Every Zone","Emergency Exits","First Aid Room","Non-slip Flooring"}'::text[], '{"Go at opening time (10 AM) — by 11:30 school groups arrive and it gets loud.","The touch pool is the highlight for younger kids. Arrive early before the crowd forms around it.","The underwater tunnel is 85 meters long. Walk it slowly — the sharks swim over you every few minutes.","Combine with COEX Mall shopping and the Starfield Library (Instagram-famous bookshelf) — they''re all connected.","The Komodo dragon exhibit is unique — COEX is one of the few Asian aquariums with one."}'::text[], '{"https://images.unsplash.com/photo-1517411032315-54ef2cb783bb?w=800&q=80","https://images.unsplash.com/photo-1551918120-9739cb430c6d?w=800&q=80","https://images.unsplash.com/photo-1551918120-9739cb430c6d?w=800&q=80"}'::text[], '5%', '{"COEX Aquarium Seoul","Seoul aquarium family","indoor Seoul kids"}'::text[], '{"parent_story": {"title": "He touched a starfish and declared himself a marine biologist", "excerpt": "My 4-year-old gently touched a starfish at the touch pool and announced ''I''m a scientist now.'' He spent the next 15 minutes carefully petting every creature with the most serious expression. Future marine biologist in the making.", "author": "Sophie, mom of 1 from Hong Kong", "fullStory": "COEX Aquarium is excellent for a rainy Seoul day. The 85-meter tunnel walkway is genuinely impressive \u2014 my kids ran back and forth as sharks passed overhead. The Amazonia zone is dark and mysterious (a bit scary for under-3s). The touch pool is well-supervised and the staff make sure kids handle the creatures gently. The connected COEX Mall has endless food options."}, "itinerary_comparison": {"halfDay": "1.5-2 hours for aquarium + Starfield Library visit", "fullDay": "Aquarium + COEX Mall shopping + Gangnam exploration + lunch", "bestFor": "Ages 2-10, rainy days, indoor activities"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('osaka-001', 'Universal Studios Japan', 'Osaka', 'Japan', 'Theme Parks', 'One of the world''s most visited theme parks, home to the spectacular Super Nintendo World. Wizarding World of Harry Potter, Jurassic Park, Minion Park, and unique Japan-only attractions like Demon Slayer and Attack on Titan VR rides.', '5-17', 4.8, '$$$', 96, '2-1-33 Sakurajima, Konohana-ku, Osaka, Japan', 'Weekdays, Tuesday-Thursday (weekends are packed)', 'https://images.unsplash.com/photo-1775144113652-6592b3ebeb06?w=800&q=80', '{"Super Nintendo World","Harry Potter World","Minion Park","Single Rider Lines","Stroller Rental","Baby Care Centers"}'::text[], '{"Height Restrictions Enforced","Ride Safety Checkpoints","Trained Staff","First Aid Stations","Lost Child Centers"}'::text[], '{"Buy the Express Pass — it''s expensive ($50-80 extra) but you WILL need it. Regular waits hit 120+ minutes on busy days.","Enter Super Nintendo World FIRST. The timed entry tickets run out by 10 AM on busy days.","The power-up band ($30) is worth it for Super Nintendo World — kids love collecting digital coins and keys.","Single rider lines cut wait times by 50-80%. If your kid is tall enough (122cm+), use them.","Eat at ''Three Broomsticks'' in Harry Potter World — the butterbeer and fish & chips are actually good.","Bring a portable charger. The USJ app drains your battery with ride wait times and park maps."}'::text[], '{"https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80","https://images.unsplash.com/photo-1513889961551-628c1e5e2ee9?w=800&q=80","https://images.unsplash.com/photo-1513889961551-628c1e5e2ee9?w=800&q=80"}'::text[], '8%', '{"Universal Studios Japan","Super Nintendo World Osaka","Osaka theme park family"}'::text[], '{"parent_story": {"title": "My son cried when we entered Nintendo World \u2014 happy tears", "excerpt": "The moment the warp pipe slide opened and Mario music blared, my 7-year-old burst into tears. ''This is the best day of my life,'' he whispered. Mine too, buddy. Mine too.", "author": "James, dad of 1 from London", "fullStory": "Universal Studios Japan is on another level from the American parks. Super Nintendo World is a masterpiece \u2014 you walk INTO a video game. The Mario Kart ride uses AR goggles that make you feel like you''re racing through the track. The attention to detail is insane (coin blocks that go ''bling'' when you punch them). Our 9-year-old wore her power-up band for the entire day and slept with it on."}, "itinerary_comparison": {"halfDay": "Super Nintendo World (3h) + 2-3 other rides + lunch", "fullDay": "SNW at open + Harry Potter + Minion Park + Hollywood Dream roller coaster", "bestFor": "Ages 6+, Nintendo/Harry Potter fans, thrill seekers"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('osaka-002', 'Osaka Aquarium Kaiyukan', 'Osaka', 'Japan', 'Zoos & Aquariums', 'One of the world''s largest and most spectacular aquariums. The centerpiece is a 5,400-ton Pacific Ocean tank housing whale sharks (the largest fish on earth), manta rays, and thousands of other creatures across 15 tanks representing the Pacific Rim.', '2-12', 4.8, '$$', 91, '1-1-10 Kaigandori, Minato-ku, Osaka, Japan', 'Weekday afternoons (2 PM onwards are less crowded than mornings)', 'https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80', '{"Whale Shark Tank","Touch Pool","Cafe with Tank View","Gift Shop","Stroller Access","Nursing Room"}'::text[], '{"Glass Barriers","Staff at Every Exhibit","Well-Marked Exits","Non-slip Walkways","First Aid"}'::text[], '{"Go in the afternoon (2 PM+). Morning crowds from schools and buses clear out by lunchtime.","The main tank has a seating area in front — sit and watch the whale sharks glide. It''s mesmerizing for kids and adults.","The cafe on the 4th floor has tables facing the main tank. Grab a seat and let the kids watch while you rest.","Touch pool is on the 3rd floor. Hand washing stations are provided. Use them — the rays have a slimy coating.","Combine with the Tempozan Giant Ferris Wheel right next door — it''s 112m high with amazing Osaka Bay views.","The aquarium is spiral-shaped — you walk down a ramp around the central tank. No elevators between floors."}'::text[], '{"https://images.unsplash.com/photo-1517411032315-54ef2cb783bb?w=800&q=80","https://images.unsplash.com/photo-1551918120-9739cb430c6d?w=800&q=80","https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80"}'::text[], '6%', '{"Osaka Aquarium","Kaiyukan","whale shark Osaka"}'::text[], '{"parent_story": {"title": "We sat in front of the whale shark tank for an hour", "excerpt": "Our 4-year-old sat cross-legged in front of the main tank for a full hour. A whale shark swam past 11 times. She counted. I just watched her face light up each time. Best hour of our Osaka trip.", "author": "Yuki, mom of 2 from Tokyo", "fullStory": "Kaiyukan is the best aquarium I''ve ever visited \u2014 and I''ve been to Monterey Bay, Shedd, and Churaumi. The spiral ramp design means you gradually descend around the central Pacific Ocean tank, seeing it from every angle. The whale sharks are breathtaking \u2014 they''re huge (up to 12m) but move with an impossible grace. The jellyfish exhibit is an otherworldly light show. The ring-tailed lemurs on the top floor are a fun surprise."}, "itinerary_comparison": {"halfDay": "2-3 hours for aquarium + Tempozan Ferris Wheel", "fullDay": "Aquarium + Ferris Wheel + Osaka Bay area + Legoland Discovery Center (nearby)", "bestFor": "All ages, especially 2-10, marine life enthusiasts"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('kualalumpur-001', 'KidZania Kuala Lumpur', 'Kuala Lumpur', 'Malaysia', 'Theme Parks', 'An award-winning indoor edutainment center where kids can try 60+ real professions in a kid-sized city. From pilot to chef to surgeon, children learn through immersive role-play in a safe, supervised indoor environment.', '4-14', 4.7, '$$', 85, 'Mutiara Damansara, Kuala Lumpur, Malaysia', 'Weekdays, right at opening (10 AM)', 'https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80', '{"Educational Programs","Role-playing Activities","English Speaking Staff","Indoor Facility","Cafe"}'::text[], '{"Supervised Activities","Child Tracking Wristbands","Emergency Protocols","Staff in Every Zone"}'::text[], '{"Book the morning session (10 AM-2 PM) — afternoon sessions are much more crowded and popular activities run out fast.","Let your child choose their own path. The pilot and firefighter activities are the most popular — go there first.","The venue is inside the Curve mall, so one parent can shop while the other supervises. Take turns.","Air conditioning is excellent. Your kids will be comfortable even on Kuala Lumpur''s hottest days.","Buy tickets online in advance — walk-in prices are higher and sessions can sell out on weekends and holidays."}'::text[], '{"https://images.unsplash.com/photo-1590559899731-a382839e5549?w=800&q=80","https://images.unsplash.com/photo-1738023354227-16a406891bd2?w=800&q=80","https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80"}'::text[], '7%', '{"KidZania Kuala Lumpur","KL indoor kids activities","educational Malaysia kids"}'::text[], '{"parent_story": {"title": "He came home and announced he''s ''retired'' now", "excerpt": "Our 7-year-old tried 10 professions in one day \u2014 pilot, firefighter, surgeon, journalist, and more. He came home exhausted, announced he was ''retired,'' and slept for 12 hours straight.", "author": "Aisha, mom of 2 from Singapore", "fullStory": "KidZania Kuala Lumpur is smaller than the Tokyo and Bangkok versions but just as engaging. The 60+ professions keep kids busy for hours. My son loved the aviation zone where he got to ''fly'' a simulated plane. The staff rotate activities throughout the day so if you miss something, it might be available later. Great value for the price."}, "itinerary_comparison": {"halfDay": "4-6 activities, 3 hours", "fullDay": "8-10 activities, 5 hours with lunch break", "bestFor": "Ages 4-10, curious kids, rainy days"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('kualalumpur-002', 'Aquaria KLCC', 'Kuala Lumpur', 'Malaysia', 'Zoos & Aquariums', 'A world-class oceanarium at the base of the Petronas Twin Towers. Walk through a 90-meter underwater tunnel surrounded by sharks, stingrays, and sea turtles. Features a touch pool and interactive feeding sessions.', '2-12', 4.7, '$$', 87, 'KLCC Convention Centre, Kuala Lumpur, Malaysia', 'Weekday mornings (10 AM opening)', 'https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80', '{"Underwater Tunnel","Touch Pool","Interactive Feeding Shows","Gift Shop","Air Conditioning"}'::text[], '{"Glass Barriers","Lifeguards at Touch Pool","Emergency Exits","First Aid"}'::text[], '{"Arrive at 10 AM opening — the school groups arrive by 11 AM and the underwater tunnel gets packed.","Check the feeding schedule at the entrance and plan your visit around the ''Dive with Sharks'' feeding at 3 PM.","The touch pool lets kids pet starfish and sea cucumbers. Hand sanitizer stations are nearby.","Combine with a visit to KLCC Park and the Petronas Twin Towers observation deck for a full day.","The aquarium is fully indoors with excellent AC — perfect for escaping KL''s afternoon heat and rain."}'::text[], '{"https://images.unsplash.com/photo-1551918120-9739cb430c6d?w=800&q=80","https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80","https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80"}'::text[], '5%', '{"Aquaria KLCC","Kuala Lumpur aquarium","KL family activities"}'::text[], '{"parent_story": {"title": "She held a starfish and didn''t scream", "excerpt": "My 4-year-old, who shrieks at the sight of a ladybug, calmly held a starfish at the touch pool. She stared at it for 5 minutes, then looked up and said ''It''s tickly, Mama.'' Pure magic.", "author": "Michelle, mom of 1 from Hong Kong", "fullStory": "Aquaria KLCC is surprisingly impressive for a mall-basement aquarium. The 90-meter tunnel is the star \u2014 you walk through it on a moving walkway while sharks and rays glide overhead. The touch pool was our daughter''s favorite. The aquarium is well-maintained and the staff clearly care about the animals. We spent 2.5 hours here and could have stayed longer."}, "itinerary_comparison": {"halfDay": "Underwater tunnel + touch pool + feeding show, 2-3 hours", "fullDay": "Aquaria + KLCC Park + Petronas Skybridge + Suria KLCC shopping", "bestFor": "Ages 2-10, marine life fans, rainy days"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('chiangmai-001', 'Elephant Nature Park', 'Chiang Mai', 'Thailand', 'Zoos & Aquariums', 'An ethical elephant rescue sanctuary in a beautiful Mae Taeng valley. No riding, no hooks — just observing, feeding, and bathing rescued elephants in their natural habitat. A life-changing experience for families.', '5-17', 4.9, '$$$', 94, 'Mae Taeng, Chiang Mai, Thailand', 'Morning session (7 AM-2 PM)', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80', '{"Feeding Platform","River Bathing","Educational Talk","Lunch Included","Souvenir Shop"}'::text[], '{"Professional Guides","Safety Briefing Required","Clear Boundaries with Elephants","First Aid Trained Staff","Minimum Age 5"}'::text[], '{"Book months in advance for the single-day visit — it sells out 4-6 weeks ahead during high season (November-February).","The minimum age for the single-day program is 5. For the overnight program, it''s 10. Don''t try to bring younger kids — they won''t refund you.","Wear dark-colored clothes that can get muddy. You''ll be in the river with the elephants and light colors show everything.","The drive from Chiang Mai city takes 1-1.5 hours. The van picks you up at 7 AM from your hotel.","No riding allowed here — and that''s the point. If a sanctuary offers elephant rides, it''s not ethical. ENP is the gold standard."}'::text[], '{"https://images.unsplash.com/photo-1550358864-518f202c02ba?w=800&q=80","https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80","https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80"}'::text[], '8%', '{"Elephant Nature Park Chiang Mai","ethical elephant sanctuary","Chiang Mai family"}'::text[], '{"parent_story": {"title": "Bathing with elephants changed how my daughter sees animals", "excerpt": "She scrubbed mud off a rescued elephant''s back and the elephant gently sprayed her with water. She laughed and cried at the same time. She asked me later ''Mama, why would anyone hurt them?'' I didn''t have a good answer.", "author": "Sarah, mom of 1 from Sydney", "fullStory": "Elephant Nature Park is not a tourist attraction \u2014 it''s a rescue and rehabilitation center. Our guide shared each elephant''s story: one was a logging elephant with a broken leg, another was rescued from a riding camp. My 9-year-old understood the mission and treated the elephants with such tenderness. This isn''t just a fun day out \u2014 it''s an education in compassion. Every family should experience this."}, "itinerary_comparison": {"halfDay": "Single-day visit: feeding + river bathing + lunch + educational talk, 7 AM-2 PM", "fullDay": "Overnight program (ages 10+): full day with elephants + accommodation + evening walk", "bestFor": "Ages 5+, ethical tourism, animal lovers"}}'::jsonb);

INSERT INTO destinations (id, name, city, country, category, description, age_range, safety_rating, price_range, popularity, location, best_time, image_url, amenities, safety_features, tips_and_tricks, gallery, commission_rate, seo_keywords, metadata)
VALUES ('chiangmai-002', 'Chiang Mai Night Safari', 'Chiang Mai', 'Thailand', 'Zoos & Aquariums', 'A unique nocturnal zoo experience where families ride a tram through open enclosures to see lions, zebras, giraffes, and other animals after dark. Includes walking trails, shows, and a kids'' playground.', '3-12', 4.6, '$$', 82, 'Doi Suthep-Pui, Chiang Mai, Thailand', 'Evening (opens 11 AM, tram rides start at 6 PM)', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80', '{"Night Tram Rides","Walking Trails","Animal Shows","Playground","Restaurants","Gift Shop"}'::text[], '{"Tram Safety Barriers","Trained Guides on Tram","Well-lit Walking Paths","First Aid Station","Security Patrols"}'::text[], '{"The night tram rides are the main event. Go for the 6 PM first session — animals are most active and the crowd is smallest.","Bring cash for animal food (carrots and bananas to feed giraffes). There are ATMs but the line is long.","The carnivore zone (lions, tigers) is impressive at night — their eyes glow in the dark. Kids find it thrilling.","The predator show at the outdoor arena is worth the 20-minute wait. Arrive early for good seats.","The temperature drops noticeably after sunset. Bring a light jacket even in the hot season."}'::text[], '{"https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&q=80","https://images.unsplash.com/photo-1564349683136-77e08dba1ef7?w=800&q=80","https://images.unsplash.com/photo-1551918120-9739cb430c6d?w=800&q=80"}'::text[], '5%', '{"Chiang Mai Night Safari","night zoo Chiang Mai","Chiang Mai family"}'::text[], '{"parent_story": {"title": "A deer ate my daughter''s shoe", "excerpt": "In the open walking zone, a friendly deer trotted up, sniffed my 5-year-old''s sparkly shoe, and nibbled it. She yelped, then laughed so hard she snorted. The deer didn''t let go for 10 seconds. Best photo of 2024.", "author": "James, dad of 2 from London", "fullStory": "Chiang Mai Night Safari is not as polished as Singapore''s version but it has a charming, raw authenticity. The open zones let animals roam freely and come right up to the tram. The giraffe feeding platform is the highlight \u2014 they stick their long necks right into the tram. The walking trails are well-lit and safe. For the price, it''s excellent value. Our kids (5 and 8) were captivated the entire 3 hours."}, "itinerary_comparison": {"halfDay": "3-4 hours: first night tram + walking trails + predator show + dinner", "fullDay": "Combine with Doi Suthep temple and Bua Thong Sticky Falls for a full Chiang Mai day", "bestFor": "Ages 3-12, evening activities, animal lovers"}}'::jsonb);


-- Update timestamps trigger
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS update_destinations_updated_at ON destinations;
CREATE TRIGGER update_destinations_updated_at
  BEFORE UPDATE ON destinations
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

-- Create useful indexes
CREATE INDEX IF NOT EXISTS idx_destinations_city ON destinations(city);
CREATE INDEX IF NOT EXISTS idx_destinations_category ON destinations(category);
CREATE INDEX IF NOT EXISTS idx_destinations_popularity ON destinations(popularity DESC);
CREATE INDEX IF NOT EXISTS idx_destinations_safety ON destinations(safety_rating DESC);
CREATE INDEX IF NOT EXISTS idx_destinations_price ON destinations(price_range);

-- Verify the data
SELECT COUNT(*) AS total_destinations FROM destinations;
